import{_ as a,o as e,c as r,O as d}from"./chunks/framework.b55d0e42.js";const g=JSON.parse('{"title":"微前端概述与方案对比","description":"","frontmatter":{},"headers":[],"relativePath":"leadingEnd/微前端/微前端-概述与方案对比.md","filePath":"leadingEnd/微前端/微前端-概述与方案对比.md","lastUpdated":1779673555000}'),l={name:"leadingEnd/微前端/微前端-概述与方案对比.md"};function i(o,t,n,s,h,u){return e(),r("div",null,t[0]||(t[0]=[d('<h1 id="微前端概述与方案对比" tabindex="-1">微前端概述与方案对比 <a class="header-anchor" href="#微前端概述与方案对比" aria-label="Permalink to &quot;微前端概述与方案对比&quot;">​</a></h1><h2 id="什么是微前端" tabindex="-1">什么是微前端 <a class="header-anchor" href="#什么是微前端" aria-label="Permalink to &quot;什么是微前端&quot;">​</a></h2><p>微前端是一种多个团队通过独立发布功能的方式来共同构建现代化 web 应用的技术手段和架构模式。</p><h3 id="核心价值" tabindex="-1">核心价值 <a class="header-anchor" href="#核心价值" aria-label="Permalink to &quot;核心价值&quot;">​</a></h3><ul><li><strong>技术栈无关</strong>：不同子应用可以使用不同技术栈</li><li><strong>独立开发部署</strong>：各团队独立迭代，互不阻塞</li><li><strong>增量升级</strong>：老旧项目可以逐步迁移，无需重写</li><li><strong>独立运行时</strong>：各子应用独立运行，故障隔离</li></ul><h2 id="主流方案对比" tabindex="-1">主流方案对比 <a class="header-anchor" href="#主流方案对比" aria-label="Permalink to &quot;主流方案对比&quot;">​</a></h2><table><thead><tr><th>方案</th><th>代表框架</th><th>原理</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>iframe</strong></td><td>原生</td><td>浏览器级别隔离</td><td>最简单，天然隔离</td><td>DOM割裂、通信复杂、性能差</td></tr><tr><td><strong>Web Components</strong></td><td>无</td><td>Shadow DOM</td><td>标准化、样式隔离</td><td>兼容性、生态不成熟</td></tr><tr><td><strong>路由分发</strong></td><td>qiankun</td><td>监听路由、加载子应用</td><td>体验好、成熟方案</td><td>需要基座改造</td></tr><tr><td><strong>Module Federation</strong></td><td>Webpack 5</td><td>运行时加载远程模块</td><td>共享依赖灵活、去中心化</td><td>Webpack 绑定</td></tr><tr><td><strong>iframe + 桥接</strong></td><td>无界</td><td>iframe + 通信桥</td><td>隔离好、体验接近 SPA</td><td>较新方案</td></tr></tbody></table><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><ul><li><strong>大厂成熟项目</strong>：qiankun（single-spa 封装）</li><li><strong>Webpack 项目</strong>：Module Federation（去中心化）</li><li><strong>追求极致隔离</strong>：无界（iframe 改进方案）</li><li><strong>简单集成</strong>：iframe + postMessage</li></ul><h2 id="核心挑战" tabindex="-1">核心挑战 <a class="header-anchor" href="#核心挑战" aria-label="Permalink to &quot;核心挑战&quot;">​</a></h2><h3 id="_1-样式隔离" tabindex="-1">1. 样式隔离 <a class="header-anchor" href="#_1-样式隔离" aria-label="Permalink to &quot;1. 样式隔离&quot;">​</a></h3><ul><li>CSS Modules / Scoped CSS</li><li>Shadow DOM</li><li>CSS 命名约定（BEM）</li></ul><h3 id="_2-javascript-沙箱" tabindex="-1">2. JavaScript 沙箱 <a class="header-anchor" href="#_2-javascript-沙箱" aria-label="Permalink to &quot;2. JavaScript 沙箱&quot;">​</a></h3><ul><li>快照沙箱（LegacySandBox）</li><li>代理沙箱（ProxySandBox）</li></ul><h3 id="_3-通信机制" tabindex="-1">3. 通信机制 <a class="header-anchor" href="#_3-通信机制" aria-label="Permalink to &quot;3. 通信机制&quot;">​</a></h3><ul><li>全局事件总线</li><li>路由参数传递</li><li>共享状态管理</li><li>自定义事件</li></ul><h3 id="_4-公共依赖" tabindex="-1">4. 公共依赖 <a class="header-anchor" href="#_4-公共依赖" aria-label="Permalink to &quot;4. 公共依赖&quot;">​</a></h3><ul><li>externals + CDN</li><li>共享模块（Module Federation shared）</li><li>公共基座库</li></ul>',18)]))}const b=a(l,[["render",i]]);export{g as __pageData,b as default};
